selector_to_html = {"a[href=\"#quickstart\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Quickstart<a class=\"headerlink\" href=\"#quickstart\" title=\"Link to this heading\">\uf0c1</a></h1><p>This page walks through the most common workflows in a few lines each.\nFor a detailed walkthrough with real data, see <a class=\"reference internal\" href=\"python_api_tutorial.html#python-api-tutorial\"><span class=\"std std-ref\">Python API Tutorial</span></a>.</p>", "a[href=\"cli.html#cli-liftover\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Plotting behaviour options<a class=\"headerlink\" href=\"#plotting-behaviour-options\" title=\"Link to this heading\">\uf0c1</a></h2>", "a[href=\"#mixed-genome-builds-with-liftover\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Mixed genome builds with liftover<a class=\"headerlink\" href=\"#mixed-genome-builds-with-liftover\" title=\"Link to this heading\">\uf0c1</a></h2><p>If your summary statistics were generated on different reference panels\n(hg18, hg19, or hg38), pycmplot can liftover hg18 and hg19 coordinates to\nhg38 before plotting. Supply the builds either through a <code class=\"docutils literal notranslate\"><span class=\"pre\">BUILD</span></code> column\nin the files or by passing <code class=\"docutils literal notranslate\"><span class=\"pre\">--build</span></code> (CLI) / <code class=\"docutils literal notranslate\"><span class=\"pre\">build_list=</span></code> (API):</p>", "a[href=\"#multi-track-linear-manhattan-plot\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Multi-track linear Manhattan plot<a class=\"headerlink\" href=\"#multi-track-linear-manhattan-plot\" title=\"Link to this heading\">\uf0c1</a></h3><p>Compare three RBC traits in a single stacked figure:</p>", "a[href=\"api/index.html#api\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">API Reference<a class=\"headerlink\" href=\"#api-reference\" title=\"Link to this heading\">\uf0c1</a></h1><p>This section documents every public function and class exposed by pycmplot.\nAll symbols listed here are importable directly from the top-level package\n(<code class=\"docutils literal notranslate\"><span class=\"pre\">from</span> <span class=\"pre\">pycmplot</span> <span class=\"pre\">import</span> <span class=\"pre\">...</span></code>) unless noted otherwise.</p>", "a[href=\"#python-api\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Python API<a class=\"headerlink\" href=\"#python-api\" title=\"Link to this heading\">\uf0c1</a></h2><p>The Python API exposes the same pipeline as the CLI, with three explicit\nsteps: (1) resolve per-file column names, (2) load and pre-process the\nsummary statistics, (3) render the plot. The rendering functions take the\n<code class=\"docutils literal notranslate\"><span class=\"pre\">sumstats_loaded</span></code> dictionary produced in step 2.</p>", "a[href=\"#next-steps\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Next steps<a class=\"headerlink\" href=\"#next-steps\" title=\"Link to this heading\">\uf0c1</a></h2>", "a[href=\"cli.html#cli\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Command-Line Interface<a class=\"headerlink\" href=\"#command-line-interface\" title=\"Link to this heading\">\uf0c1</a></h1><p>pycmplot exposes a full command-line interface that mirrors the Python API.\nAfter installation, the <code class=\"docutils literal notranslate\"><span class=\"pre\">pycmplot</span></code> command is available in your PATH.</p>", "a[href=\"#circular-circos-style-manhattan-plot\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Circular (Circos-style) Manhattan plot<a class=\"headerlink\" href=\"#circular-circos-style-manhattan-plot\" title=\"Link to this heading\">\uf0c1</a></h3>", "a[href=\"#qq-plots\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">QQ plots<a class=\"headerlink\" href=\"#qq-plots\" title=\"Link to this heading\">\uf0c1</a></h3><p>Each of the QQ functions accepts the <code class=\"docutils literal notranslate\"><span class=\"pre\">pvals</span></code> dictionary returned by\n<a class=\"reference internal\" href=\"api/io.html#pycmplot.io.load\" title=\"pycmplot.io.load\"><code class=\"xref py py-func docutils literal notranslate\"><span class=\"pre\">load()</span></code></a>:</p>", "a[href=\"api/io.html#pycmplot.io.load\"]": "<dt class=\"sig sig-object py\" id=\"pycmplot.io.load\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pycmplot.io.</span></span><span class=\"sig-name descname\"><span class=\"pre\">load</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">sum_stats</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><span class=\"pre\">list</span><span class=\"p\"><span class=\"pre\">[</span></span><span class=\"pre\">str</span><span class=\"p\"><span class=\"pre\">]</span></span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">labels</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><span class=\"pre\">list</span><span class=\"p\"><span class=\"pre\">[</span></span><span class=\"pre\">str</span><span class=\"p\"><span class=\"pre\">]</span></span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">logp</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><span class=\"pre\">bool</span></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">False</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">trim_pval</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><span class=\"pre\">float</span><span class=\"w\"> </span><span class=\"p\"><span class=\"pre\">|</span></span><span class=\"w\"> </span><span class=\"pre\">None</span></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">file_info</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><span class=\"pre\">dict</span><span class=\"w\"> </span><span class=\"p\"><span class=\"pre\">|</span></span><span class=\"w\"> </span><span class=\"pre\">None</span></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">sort_tracks</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><span class=\"pre\">str</span><span class=\"w\"> </span><span class=\"p\"><span class=\"pre\">|</span></span><span class=\"w\"> </span><span class=\"pre\">None</span></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">table_out</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><span class=\"pre\">str</span><span class=\"w\"> </span><span class=\"p\"><span class=\"pre\">|</span></span><span class=\"w\"> </span><span class=\"pre\">None</span></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">signif_threshold</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><span class=\"pre\">float</span><span class=\"w\"> </span><span class=\"p\"><span class=\"pre\">|</span></span><span class=\"w\"> </span><span class=\"pre\">None</span></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">signif_line</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><span class=\"pre\">bool</span><span class=\"w\"> </span><span class=\"p\"><span class=\"pre\">|</span></span><span class=\"w\"> </span><span class=\"pre\">float</span><span class=\"w\"> </span><span class=\"p\"><span class=\"pre\">|</span></span><span class=\"w\"> </span><span class=\"pre\">None</span></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">suggest_threshold</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><span class=\"pre\">float</span><span class=\"w\"> </span><span class=\"p\"><span class=\"pre\">|</span></span><span class=\"w\"> </span><span class=\"pre\">None</span></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">1e-05</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">highlight</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><span class=\"pre\">bool</span><span class=\"w\"> </span><span class=\"p\"><span class=\"pre\">|</span></span><span class=\"w\"> </span><span class=\"pre\">None</span></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">False</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">highlight_thresh</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><span class=\"pre\">float</span><span class=\"w\"> </span><span class=\"p\"><span class=\"pre\">|</span></span><span class=\"w\"> </span><span class=\"pre\">None</span></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">resources</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference internal\" href=\"api/resources.html#pycmplot.resources.ResourceConfig\" title=\"pycmplot.resources.ResourceConfig\"><span class=\"pre\">ResourceConfig</span></a><span class=\"w\"> </span><span class=\"p\"><span class=\"pre\">|</span></span><span class=\"w\"> </span><span class=\"pre\">None</span></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">compute_pvals</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><span class=\"pre\">bool</span></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">False</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">auto_thin</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><span class=\"pre\">bool</span></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">True</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">auto_thin_threshold</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><span class=\"pre\">float</span></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">2.0</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">auto_thin_max_below</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><span class=\"pre\">int</span></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">200000</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">cache</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><span class=\"pre\">bool</span></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">False</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">cache_dir</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><span class=\"pre\">str</span><span class=\"w\"> </span><span class=\"p\"><span class=\"pre\">|</span></span><span class=\"w\"> </span><span class=\"pre\">PathLike</span></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">'.pycmplot_cache'</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">resume</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><span class=\"pre\">bool</span></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">True</span></span></em><span class=\"sig-paren\">)</span><a class=\"reference internal\" href=\"_modules/pycmplot/io.html#load\"><span class=\"viewcode-link\"><span class=\"pre\">[source]</span></span></a></dt><dd><p>Load summary statistics, run liftover, extract lead SNPs, and compute merged Circos sector sizes.</p><p>This is the primary data-loading function for the plotting pipeline.\nFor each track it reads the file using the column mapping from\n<code class=\"docutils literal notranslate\"><span class=\"pre\">file_info</span></code>, optionally filters by <code class=\"docutils literal notranslate\"><span class=\"pre\">trim_pval</span></code>, normalises\nchromosome names (<code class=\"docutils literal notranslate\"><span class=\"pre\">chr</span></code> prefix stripped; <code class=\"docutils literal notranslate\"><span class=\"pre\">23</span></code> to <code class=\"docutils literal notranslate\"><span class=\"pre\">X</span></code>, <code class=\"docutils literal notranslate\"><span class=\"pre\">24</span></code> to\n<code class=\"docutils literal notranslate\"><span class=\"pre\">Y</span></code>, <code class=\"docutils literal notranslate\"><span class=\"pre\">M</span></code> / <code class=\"docutils literal notranslate\"><span class=\"pre\">MTDNA</span></code> to <code class=\"docutils literal notranslate\"><span class=\"pre\">MT</span></code>), lifts over hg19 coordinates when a\nbuild column is present, and extracts lead SNPs. After all tracks are\nloaded it builds the hits summary table, derives significance\nthresholds, optionally sorts tracks, and computes the merged\nsector-size dict consumed by both plotters.</p><p class=\"rubric\">Examples</p></dd>", "a[href=\"python_api_tutorial.html#python-api-tutorial\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Python API Tutorial<a class=\"headerlink\" href=\"#python-api-notebook\" title=\"Link to this heading\">\uf0c1</a></h1><p>The interactive tutorial below demonstrates the full Python API using real\nsummary statistics data. It covers data loading, single- and multi-track\nlinear Manhattan plots, circular Manhattan plots, liftover, and the hits\nsummary table.</p>", "a[href=\"#command-line\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Command line<a class=\"headerlink\" href=\"#command-line\" title=\"Link to this heading\">\uf0c1</a></h2><p>Most users will use the CLI. The typical invocation for a multi-track plot is:</p>", "a[href=\"#input-file-format\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Input file format<a class=\"headerlink\" href=\"#input-file-format\" title=\"Link to this heading\">\uf0c1</a></h2><p>pycmplot accepts any whitespace- or comma-delimited summary statistics file,\nincluding gzip-compressed (<code class=\"docutils literal notranslate\"><span class=\"pre\">.gz</span></code>) files. Required columns (auto-detected from\ncommon names) are:</p>", "a[href=\"#linear-manhattan-plot-single-trait\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Linear Manhattan plot (single trait)<a class=\"headerlink\" href=\"#linear-manhattan-plot-single-trait\" title=\"Link to this heading\">\uf0c1</a></h3>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: true, theme: 'light-border',

            });
        };
    };
    console.log("tippy tips loaded!");
};
